let item = $input.first().json;
let text = '';

// 1. 终极抓取逻辑 (🌟 新增了对 OpenAI/Gemma 标准返回格式的支持)
if (item.choices?.[0]?.message?.content) {
    text = item.choices[0].message.content;
}
else if (item.content && typeof item.content === 'string') {
    text = item.content;
}
else if (item.content?.parts?.[0]?.text) {
    text = item.content.parts[0].text;
}
else if (item.candidates?.[0]?.content?.parts?.[0]?.text) {
    text = item.candidates[0].content.parts[0].text;
}
else if (item.output) {
    text = item.output;
}
else if (item.text) {
    text = item.text;
}

// 2. 安全清理
text = text.replace(/```json/gi, '').replace(/```/g, '').trim();

// 3. 安全解析 JSON
let data = {};
try {
    let match = text.match(/\{[\s\S]*\}/);
    data = match ? JSON.parse(match[0]) : JSON.parse(text);
} catch (error) {
    // 🌟 报错时输出 text 变量，方便一眼看出是抓取失败还是 JSON 真有语法错误
    throw new Error("⚠️ 拦截成功：大模型本次生成的 JSON 格式有语法错误，或者文本抓取失败！\n提取到的文本内容为：\n" + text);
}

// 🌟 提取表单源头的数据，防止数据在此节点丢失！
const formData = $('产品信息').first().json;

// 4. 标准化数组包装输出（完整透传所有参数）
return [{
  json: {
    product_name: data.product_name || '',
    category: data.category || '',
    visual_features: Array.isArray(data.visual_features) ? data.visual_features.join(', ') : (data.visual_features || ''),
    target_audience: data.target_audience || '',
    extreme_pain_point: data.extreme_pain_point || data.pain_point || '',
    core_solution: data.core_solution || '',
    visual_hook_suggestion: data.visual_hook_suggestion || '',
    key_differentiators: Array.isArray(data.key_differentiators) ? data.key_differentiators.join(', ') : (data.key_differentiators || ''),
    suggested_style: data.suggested_style || '简约',

    // 👇 下面这些是新增的修复代码：强行把表单设置继承下来
    videoLanguage: formData.videoLanguage || 'Portuguese (Brazil)',
    videoDuration: formData.videoDuration || 30,
    numberOfVideos: formData.numberOfVideos || 1,
    customerEmail: formData.customerEmail || '',
    customerName: formData.customerName || '',
    customerId: formData.customerId || '',

    product_image_base64: $('提取产品图片').first().json.product_image_base64 || '',

    // 🌟 Catbox I2V: 从数据流上游显式继承产品图片公网 URL
    product_public_image_url: $('📎 提取产品图URL').first().json.product_public_image_url || ''
  }
}];

// 注意：这里改成了 $input.first() 来适配 All Items 模式
const item = $input.first().json;
let text = '';

// 精准抓取 DeepSeek 数据
if (item.choices && item.choices[0] && item.choices[0].message && item.choices[0].message.content) {
    text = item.choices[0].message.content;
} else {
    throw new Error("找不到 DeepSeek 的数据，请检查上游节点。");
}

// 强力清理 Markdown 标记
text = text.replace(/```json/gi, '').replace(/```/g, '').trim();

// 安全解析 JSON（带容错正则匹配）
let data = {};
try {
    let match = text.match(/\{[\s\S]*\}/);
    data = match ? JSON.parse(match[0]) : JSON.parse(text);
} catch (error) {
    throw new Error("JSON 解析失败。提取到的文本为: " + text);
}

// 🌟 从上游节点获取变体元数据
const variantData = $('🎲 提示词变体生成器').first().json;
const videoDuration = parseInt($('产品信息').first().json.videoDuration) || 30;

// 🔢 极简模式：统一每段固定 10 秒（20秒→2段，30秒→3段）
// 提取核心 segments 数组
let segments = data.segments || (Array.isArray(data) ? data : []);
const totalSegments = segments.length;

// 🌟 获取产品图片（用于下游 Seedance I2V）
const productImage = $('📊 解析产品分析').first().json.product_image_base64 || '';
// 🌟 Catbox I2V: 从数据流主干继承产品图片公网 URL，广播至每一个分镜切片
const productPublicImageUrl = $('📊 解析产品分析').first().json.product_public_image_url || '';

// 重新映射数据格式。输出裂变后的数组！
return segments.map((seg, index) => ({
  json: {
    variant_index: variantData.variant_index || 1,
    hook_angle: variantData.hook_angle || '',
    total_variants: variantData.total_variants || 1,
    segment_index: seg.segment_index || (index + 1),
    segment_type: seg.segment_type || 'clip',

    // 🔢 【核心修复】强制使用计算时长，绝不回退到大模型返回值
    duration_seconds: 10,

    // 🏷️ 【新增】尾段标记：下游 Seedance 据此决定 T2V 或 I2V 路线
    is_last_segment: index === totalSegments - 1,

    visual_prompt: (seg.prompt || seg.visual_prompt || '').substring(0, 900),
    prompt: (seg.prompt || seg.visual_prompt || '').substring(0, 900),
    voice_id: seg.voice_id || '',
    narration: seg.narration || '',
    text_overlay: seg.text_overlay || '',

    product_image_base64: productImage,

    // 🌟 Catbox I2V: 广播公网图片 URL 到每一个分镜切片
    product_public_image_url: productPublicImageUrl
  }
}));

const items = $input.all();

return [{
  json: {
    status: 'segments_complete',
    total_segments: items.length,
    total_duration: items.reduce((sum, item) => sum + (item.json.duration_seconds || 5), 0),
    variant_index: items[0]?.json?.variant_index || 1,
    hook_angle: items[0]?.json?.hook_angle || '',
    total_variants: items[0]?.json?.total_variants || 1,
    segments: items.map(item => ({
      segment_index: item.json.segment_index,
      segment_type: item.json.segment_type,
      video_url: item.json.video_url || '',
      audio_url: item.json.audio_url || '',
      narration: item.json.narration || '',
      text_overlay: item.json.text_overlay || '',
      duration_seconds: item.json.duration_seconds || 5
    })),
    customer_email: $('产品信息').first().json.customerEmail || '',
    customer_name: $('产品信息').first().json.customerName || '',
    customer_id: $('产品信息').first().json.customerId || '',
    product_name: $('📊 解析产品分析').first().json.product_name || ''
  }
}];

