={{
  (() => {
    const dur = Math.min($json.duration_seconds || 10, 10);
    const visualPrompt = $json.visual_prompt || $json.prompt || '';
    const narration = $json.narration || '';

    // 🌟 直接读取数据流中的图片 URL，100% 稳定获取
    const productImageUrl = $json.product_public_image_url || '';

    let fullPrompt = visualPrompt;
    if (narration) {
      fullPrompt += '\n\n画面中的人物正在面对镜头说话，请原生生成以下葡萄牙语台词的朗读语音并严格同步嘴型（仅作为语音发音，严禁在画面中显示任何文字）：\n"' + narration + '"';
    }

    const contentPayload = [
      { type: 'text', text: fullPrompt }
    ];

    if (productImageUrl) {
      contentPayload.push({
        type: 'image_url',
        image_url: { url: productImageUrl }
      });
    }

    return {
      model: 'doubao-seedance-2-0-mini-260615',
      content: contentPayload,
      generate_audio: true,
      ratio: '9:16',
      resolution: '480p',
      duration: dur,
      watermark: false
    };
  })()
}}

