const seedanceResp = $input.item.json;
const taskId = seedanceResp.id || seedanceResp.task_id;
const seg = $('💾 保存分镜上下文').item.json;

if (!taskId) {
  throw new Error('Seedance did not return task_id. Response: ' + JSON.stringify(seedanceResp).substring(0, 200));
}

return {
  json: {
    task_id: taskId,
    attempt: 0,
    max_attempts: 60,
    variant_index: seg.variant_index || 1,
    hook_angle: seg.hook_angle || '',
    total_variants: seg.total_variants || 1,
    segment_index: seg.segment_index,
    segment_type: seg.segment_type,
    duration_seconds: seg.duration_seconds,
    visual_prompt: seg.visual_prompt,
    text_overlay: seg.text_overlay,
    narration: seg.narration,
    voice_id: seg.voice_id
  }
};

const statusResp = $input.item.json;
const prevData = $('⏳ 等待轮询').item.json;

// 核心修改：去掉了最外层的 [ ]，直接返回 Object
return {
  json: {
    ...prevData,
    status: statusResp.status || statusResp.state,
    video_url: statusResp.output?.video_url || statusResp.result?.video_url || statusResp.video_url || null,
    audio_url: statusResp.output?.audio_url || statusResp.result?.audio_url || null,
    raw_response: statusResp
  }
};

const data = $input.item.json;
const attempt = (data.attempt || 0) + 1;

if (attempt > (data.max_attempts || 60)) {
  throw new Error('Seedance task ' + data.task_id + ' timed out after ' + attempt + ' attempts');
}

// 核心修改：去掉了最外层的 [ ]，直接返回 Object
return {
  json: {
    ...data,
    attempt: attempt
  }
};

const data = $input.item.json;

// 提取 Seedance 返回的原生视频 URL
const videoUrl = data.video_url || data.raw_response?.content?.video_url || data.raw_response?.output?.video_url || data.raw_response?.result?.video_url || '';

return {
  json: {
    segment_index: data.segment_index,
    segment_type: data.segment_type,
    duration_seconds: data.duration_seconds,
    visual_prompt: data.visual_prompt,
    text_overlay: data.text_overlay,
    narration: data.narration,
    video_url: videoUrl,
    audio_url: '',
    variant_index: data.variant_index || 1,
    hook_angle: data.hook_angle || '',
    total_variants: data.total_variants || 1,
    task_id: data.task_id,
    status: 'done'
  }
};

const summary = $input.first().json;
const segments = summary.segments || [];

const clipFiles = [];
const audioFiles = [];
let totalDuration = 0;

for (const seg of segments) {
  if (seg.video_url) {
    clipFiles.push(seg.video_url);
    totalDuration += seg.duration_seconds || 5;
  }
  // 🎵 同步收集音频URL，用于 FFmpeg 双轨道音视频合成
  if (seg.audio_url) {
    audioFiles.push(seg.audio_url);
  }
}

if (clipFiles.length === 0) {
  throw new Error("没有找到任何视频片段，无法拼接");
}

const timestamp = new Date().toISOString().replace(/[:.]/g, "-");
const outputDir = "/path/to/n8n-output";
const outputFile = outputDir + "/final_" + timestamp + ".mp4";

return [{
  json: {
    clip_files: clipFiles,
    audio_files: audioFiles,
    output_file: outputFile,
    threads: 4,
    total_segments: segments.length,
    total_duration: totalDuration,
    variant_index: summary.variant_index || 1,
    hook_angle: summary.hook_angle || "",
    total_variants: summary.total_variants || 1,
    customer_email: summary.customer_email,
    customer_name: summary.customer_name,
    customer_id: summary.customer_id,
    product_name: summary.product_name
  }
}];

const concatResp = $input.item.json;
const summaryNode = $("🔗 构建FFmpeg请求").first().json;

if (concatResp.status === "error") {
  throw new Error("FFmpeg 拼接失败: " + (concatResp.message || "未知错误"));
}

return {
  json: {
    final_video_url: concatResp.output_file || summaryNode.output_file,
    render_id: "ffmpeg-local",
    total_duration: summaryNode.total_duration || 30,
    variant_index: summaryNode.variant_index || 1,
    hook_angle: summaryNode.hook_angle || "",
    total_variants: summaryNode.total_variants || 1,
    customer_email: summaryNode.customer_email || "",
    customer_name: summaryNode.customer_name || "",
    customer_id: summaryNode.customer_id || "",
    product_name: summaryNode.product_name || "",
    status: "complete"
  }
};

// 因为切换到了 All Items 模式，这里改回 .first()
const product = $input.first().json;
const videoLang = product.videoLanguage || 'Portuguese (Brazil)';
const isPortuguese = videoLang.includes('Portuguese');
const count = parseInt(product.numberOfVideos) || 3;

// 9 种爆款 hook 角度池
const anglePool = [
  { pt: '翻车现场', en: 'Epic Fail Moment', style: 'panic, authentic, relatable', emotion_pt: 'desespero e frustração', emotion_en: 'desperation and frustration' },
  { pt: '素人见证', en: 'Real Person Testimonial', style: 'testimonial, tearful, grateful', emotion_pt: 'alívio e gratidão', emotion_en: 'relief and gratitude' },
  { pt: '极限测评', en: 'Extreme Challenge Test', style: 'extreme test, scientific, shocking', emotion_pt: 'choque e surpresa', emotion_en: 'shock and surprise' },
  { pt: '反差对比', en: 'Before vs After Split', style: 'split screen, dramatic contrast', emotion_pt: 'incredulidade e desejo', emotion_en: 'disbelief and desire' },
  { pt: '明星体验', en: 'Luxury Experience', style: 'glamorous, aspirational, premium', emotion_pt: 'admiração e vontade', emotion_en: 'admiration and craving' },
  { pt: '专家解析', en: 'Expert Breakdown', style: 'educational, authoritative', emotion_pt: 'confiança e respeito', emotion_en: 'confidence and trust' },
  { pt: '情景喜剧', en: 'Relatable Skit', style: 'funny, everyday humor', emotion_pt: 'identificação e riso', emotion_en: 'relatability and laughter' },
  { pt: '悬念揭秘', en: 'Mystery Reveal', style: 'suspense, curiosity, reveal', emotion_pt: 'curiosidade intensa', emotion_en: 'intense curiosity' },
  { pt: '快节奏混剪', en: 'Fast Montage', style: 'high energy, rapid cuts, dynamic', emotion_pt: 'empolgação total', emotion_en: 'total excitement' }
];

const selected = [];
for (let i = 0; i < count; i++) {
  const angle = anglePool[i % anglePool.length];
  selected.push({
    ...product,
    variant_index: i + 1,
    hook_angle: isPortuguese ? angle.pt : angle.en,
    hook_style: angle.style,
    hook_emotion: isPortuguese ? angle.emotion_pt : angle.emotion_en,
    total_variants: count
  });
}

// 裂变输出：吐出包含 3 个变体的数组
return selected.map(item => ({ json: item }));

const item = $input.first();

if (item.binary && item.binary.productImage) {
  // 强制从 n8n 的硬盘/内存中提取真实的二进制 Buffer
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'productImage');
  // 将真实的二进制文件转换为 base64 字符串
  const base64Data = buffer.toString('base64');
  const mimeType = item.binary.productImage.mimeType;

  // 拼接完整的 Data URL 并塞回 json
  item.json.product_image_base64 = `data:${mimeType};base64,${base64Data}`;
}

return item;

